import type { Bindings } from "../../types";
import { brandMatch, normalizeUrl } from "./brand";
import { buildPayload } from "../qr/content";
import { encodeMatrix } from "../qr/encoder";
import { renderSvg } from "../qr/render-svg";

/**
 * QR Wallpaper — an AI-generated, brand-styled phone background with a real,
 * scannable QR composited on top.
 *
 * The background is generated by an image model (native FLUX). The QR itself is
 * NEVER drawn by the image model (that produces unscannable codes) — the client
 * composites our programmatic, scannable QR onto the background at the chosen
 * region. This module returns the background + the QR SVG + a layout spec.
 */

// Primary image generator: fal.ai FLUX.2 — the latest, most refined BFL model
// (premium silky/cinematic output, ~3s, honors custom portrait dimensions).
// Used when FAL_KEY is configured. Rendered larger than the CF fallback for a
// crisper composite (canvas is 1080x1800).
const FAL_IMAGE_MODEL = "fal-ai/flux-2";
const FAL_W = 864;
const FAL_H = 1440;

// Fallback chain (native Workers AI, gateway-free) when fal is unavailable.
const IMAGE_MODELS = [
  "@cf/leonardo/phoenix-1.0", // most elegant; returns binary
  "@cf/black-forest-labs/flux-1-schnell", // fast fallback; returns base64
];
const IMG_W = 768;
const IMG_H = 1280;

// Native text model used to turn a brand's description into a visual scene motif.
const TEXT_MODEL = "@cf/meta/llama-3.3-70b-instruct-fp8-fast";
const VISION_MODEL = "@cf/meta/llama-3.2-11b-vision-instruct";

export type WallpaperStyle = "mesh" | "aurora" | "waves" | "minimal" | "scene";
export type WallpaperPlacement = "top" | "center" | "bottom";

export const WALLPAPER_STYLES: WallpaperStyle[] = ["mesh", "scene", "aurora", "waves", "minimal"];
export const WALLPAPER_PLACEMENTS: WallpaperPlacement[] = ["top", "center", "bottom"];

export interface WallpaperResult {
  /** AI background; null when image gen was unavailable (client paints the gradient). */
  backgroundDataUrl: string | null;
  /** whether backgroundDataUrl came from the image model */
  aiBackground: boolean;
  /** always-available brand gradient so the wallpaper never fully fails */
  gradient: { from: string; via: string; to: string };
  qrSvg: string;
  layout: { placement: WallpaperPlacement; qrFraction: number };
  palette: { fg: string; bg: string; accent: string };
  title: string;
  /** brand/theme source host the look was derived from (e.g. "gamebyte.ai") */
  source: string;
  /** host the QR actually points to (e.g. "linkedin.com") — equals source unless decoupled */
  target: string;
  style: WallpaperStyle;
  // --- poster overlay (composited crisply by the client; never AI-drawn) ---
  /** brand mark (data URL) for the top of the poster, if available */
  logo?: string;
  /** brand name shown as the wordmark (e.g. "onGame") */
  wordmark: string;
  /** short brand subtitle under the wordmark (e.g. "AI-powered game creation") */
  subtitle?: string;
  /** punchy footer tagline, "WORD · WORD · WORD" (omitted if unavailable) */
  tagline?: string;
  /** vivid brand glow colour used for accents on the dark poster */
  glow: string;
}

// All styles render on a DARK, luxe canvas (the brand colour appears as glow), so
// the composited logo, QR card and tagline read crisply — a meeting-ready poster.
const STYLE_PROMPT: Record<WallpaperStyle, string> = {
  mesh: "soft glowing gradient mesh, blurred luminous colour fields drifting over deep black",
  aurora: "ethereal aurora light ribbons glowing over deep black, luminous bokeh haze",
  waves: "elegant glowing wave curves and silky rim-lit folds flowing over black",
  minimal: "a few delicate glowing curves over a vast black canvas, immense calm empty space",
  // Themed/illustrative: a dark, atmospheric scene evoking what the brand does
  // (motif is woven into the prompt head), still calm enough for the overlay.
  scene: "dark atmospheric illustrative scene, moody depth, cinematic rim light, concept-art quality",
};

/** Premium quality cues appended to every wallpaper prompt. */
const QUALITY_CUES =
  "elegant rim light, smooth glowing accents, generous dark negative space, subtle bokeh, minimal, refined, volumetric lighting, ultra high quality, 8k, award-winning, cinematic, sophisticated, tasteful, premium";

/** Dedicated negative prompt (Leonardo/SDXL honor this field — keeps it clean). */
export const WALLPAPER_NEGATIVE =
  "text, words, letters, typography, watermark, signature, logo, qr code, phone, smartphone, device, screen, ui, app interface, frame, border, mockup, bezel, person, hand, low quality, blurry, noisy, jpeg artifacts, deformed, cluttered, oversaturated";

/** Clean display host for a URL (e.g. "linkedin.com"), or the trimmed input if unparseable. */
export function displayHost(raw: string): string {
  const u = normalizeUrl(raw);
  return u ? u.hostname.replace(/^www\./, "") : (raw || "").trim();
}

/** A coarse color name from a hex, so the image prompt reads naturally. */
export function hexToName(hex: string): string {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return "neutral";
  const n = parseInt(m[1], 16);
  const r = (n >> 16) & 255,
    g = (n >> 8) & 255,
    b = n & 255;
  const max = Math.max(r, g, b),
    min = Math.min(r, g, b);
  const l = (max + min) / 2 / 255;
  if (max - min < 24) return l < 0.2 ? "near-black" : l > 0.85 ? "off-white" : "slate grey";
  let h = 0;
  const d = max - min;
  if (max === r) h = ((g - b) / d) % 6;
  else if (max === g) h = (b - r) / d + 2;
  else h = (r - g) / d + 4;
  h = (h * 60 + 360) % 360;
  const names: [number, string][] = [
    [15, "red"], [45, "orange"], [70, "amber"], [160, "green"],
    [195, "teal"], [255, "blue"], [290, "indigo"], [330, "magenta"], [360, "red"],
  ];
  const base = names.find(([deg]) => h <= deg)?.[1] ?? "blue";
  return l < 0.35 ? `deep ${base}` : l > 0.7 ? `soft ${base}` : base;
}

function clampByte(n: number): number {
  return Math.max(0, Math.min(255, Math.round(n)));
}

/** Scale a #RRGGBB toward black (<1) or white (>1). Falls back to a teal. */
export function shadeHex(hex: string, factor: number): string {
  const m = /^#?([0-9a-f]{6})$/i.exec((hex || "").trim());
  if (!m) return factor < 1 ? "#063040" : "#3FB6D6";
  const n = parseInt(m[1], 16);
  let r = (n >> 16) & 255,
    g = (n >> 8) & 255,
    b = n & 255;
  if (factor >= 1) {
    // lighten toward white
    const t = factor - 1;
    r = r + (255 - r) * t;
    g = g + (255 - g) * t;
    b = b + (255 - b) * t;
  } else {
    r *= factor;
    g *= factor;
    b *= factor;
  }
  return "#" + [r, g, b].map((c) => clampByte(c).toString(16).padStart(2, "0")).join("");
}

function luminance(hex: string): number {
  const m = /^#?([0-9a-f]{6})$/i.exec((hex || "").trim());
  if (!m) return 0.5;
  const n = parseInt(m[1], 16);
  return ((n >> 16) & 255) * 0.299 + ((n >> 8) & 255) * 0.587 + (n & 255) * 0.114;
}

/**
 * A vivid brand glow colour that pops on a dark background. Boosts dark accents,
 * and falls back to a tasteful cool blue when the brand is essentially greyscale.
 */
export function glowColor(accent: string): string {
  const m = /^#?([0-9a-f]{6})$/i.exec((accent || "").trim());
  if (!m) return "#5B8CFF";
  const n = parseInt(m[1], 16);
  let r = (n >> 16) & 255,
    g = (n >> 8) & 255,
    b = n & 255;
  const max = Math.max(r, g, b),
    min = Math.min(r, g, b);
  const sat = max === 0 ? 0 : (max - min) / max;
  if (sat < 0.15) return "#5B8CFF"; // greyscale brand → cool default glow
  if (max < 150) {
    // dark accent → scale up so it actually glows on black, keeping its hue
    const f = 150 / Math.max(max, 1);
    r *= f;
    g *= f;
    b *= f;
  }
  return "#" + [r, g, b].map((c) => clampByte(c).toString(16).padStart(2, "0")).join("");
}

/** The brand name (wordmark) from the page title, else the host's main label. */
export function brandName(title: string, source: string): string {
  const t = (title || "").trim();
  if (t) {
    const first = t.split(/\s*[|–—·:]\s*|\s+-\s+|\s*[•]\s*/)[0].trim();
    if (first.length >= 2 && first.length <= 22) return first;
  }
  const label = (source || "").split(".")[0];
  return label ? label.charAt(0).toUpperCase() + label.slice(1) : t || source || "";
}

/** A short subtitle from the brand description (first clause, capped). */
export function subtitleFrom(description?: string): string {
  let d = (description || "").replace(/\s+/g, " ").trim();
  if (!d) return "";
  d = d.split(/(?:[.|•·]| [–—-] )/)[0].trim();
  if (d.length > 42) d = d.slice(0, 42).replace(/\s+\S*$/, "").trim();
  return d;
}

/** A dark, luxe brand gradient (always available, even with no AI image). */
export function gradientFromPalette(palette: { fg: string; accent: string }): {
  from: string;
  via: string;
  to: string;
} {
  // Near-black canvas with a faint brand tint in the middle; the client adds a
  // soft radial brand glow on top so it matches the AI dark-luxe look.
  return { from: "#0d0d12", via: shadeHex(glowColor(palette.accent), 0.32), to: "#070709" };
}

/**
 * Build the image-generation prompt for a brand wallpaper. Pure + testable.
 * `vibe` is an optional short brand style descriptor (from the brand image) so
 * the texture matches the brand's actual aesthetic, not just its color.
 * Describes a full-bleed texture — NOT a "phone wallpaper", which makes the model
 * paint a phone device/frame inside the image. Negatives live in WALLPAPER_NEGATIVE.
 */
export function buildWallpaperPrompt(
  accent: string,
  style: WallpaperStyle,
  placement: WallpaperPlacement,
  vibe?: string,
  motif?: string,
): string {
  const color = hexToName(accent);
  // Every wallpaper is a DARK luxe backdrop with the brand colour as glow. The
  // "scene" style additionally leads with the brand's subject motif (what it
  // does) so a game studio gets a moody game world, not just a glow.
  const head =
    style === "scene"
      ? `premium dark luxe wallpaper, deep near-black background, atmospheric ${color} glow${motif && motif.trim() ? `, themed around ${motif.trim()}` : ""}`
      : `premium dark luxe wallpaper, deep near-black background with soft glowing ${color} light`;
  return [
    head,
    vibe && vibe.trim() ? vibe.trim() : "",
    STYLE_PROMPT[style],
    QUALITY_CUES,
    "full-bleed, seamless, cohesive composition",
    `calm empty space toward the center for an overlaid logo and code`,
  ]
    .filter(Boolean)
    .join(", ");
}

/** Vertical placement → relative QR size fraction of the wallpaper width. */
export function placementLayout(placement: WallpaperPlacement): { placement: WallpaperPlacement; qrFraction: number } {
  // Prominent enough to scan from the image itself with any reader, not just a
  // focused phone camera.
  return { placement, qrFraction: 0.54 };
}

function bytesToBase64(bytes: Uint8Array): string {
  let bin = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    bin += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(bin);
}

/** Model-specific input. FLUX uses `steps`; Leonardo/SDXL use num_steps + guidance + negative_prompt. */
function inputFor(model: string, prompt: string, negative: string): Record<string, unknown> {
  const base = { prompt, width: IMG_W, height: IMG_H };
  if (model.includes("flux")) return { ...base, steps: 6 };
  // Leonardo Phoenix/Lucid: more steps + guidance + a real negative prompt = nicer output.
  return { ...base, num_steps: 25, guidance: 6, negative_prompt: negative };
}

/** Run one image model and normalize its output (base64 OR binary) to a data URL. */
async function runImageModel(
  env: Bindings,
  model: string,
  prompt: string,
  negative: string,
): Promise<string | null> {
  const out = (await env.AI.run(model, inputFor(model, prompt, negative))) as unknown;
  // FLUX-style: { image: base64 }
  if (out && typeof (out as { image?: unknown }).image === "string") {
    return `data:image/jpeg;base64,${(out as { image: string }).image}`;
  }
  // Leonardo/SDXL-style: raw binary (stream / buffer)
  let bytes: Uint8Array | null = null;
  if (out instanceof ReadableStream) bytes = new Uint8Array(await new Response(out).arrayBuffer());
  else if (out instanceof ArrayBuffer) bytes = new Uint8Array(out);
  else if (out instanceof Uint8Array) bytes = out;
  if (bytes && bytes.length) return `data:image/jpeg;base64,${bytesToBase64(bytes)}`;
  return null;
}

/**
 * Generate a background with fal.ai FLUX.2 (sync HTTP). Returns a data URL —
 * fal serves the image from its CDN, so we inline it here to keep it cacheable
 * in KV and free of cross-origin canvas taint on the client. null on any failure.
 * (FLUX has no negative-prompt input; the positive prompt carries the intent.)
 */
async function falImage(env: Bindings, prompt: string): Promise<string | null> {
  if (!env.FAL_KEY) return null;
  try {
    const res = await fetch(`https://fal.run/${FAL_IMAGE_MODEL}`, {
      method: "POST",
      headers: {
        Authorization: `Key ${env.FAL_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        prompt,
        image_size: { width: FAL_W, height: FAL_H },
        num_images: 1,
        output_format: "jpeg",
      }),
    });
    if (!res.ok) {
      console.error(`[wallpaper] fal ${res.status}:`, await res.text().catch(() => ""));
      return null;
    }
    const data = (await res.json()) as { images?: { url?: string }[] };
    const imgUrl = data.images?.[0]?.url;
    if (!imgUrl) return null;
    const imgRes = await fetch(imgUrl);
    if (!imgRes.ok) return null;
    const bytes = new Uint8Array(await imgRes.arrayBuffer());
    if (!bytes.length) return null;
    const mime = (imgRes.headers.get("content-type") || "image/jpeg").split(";")[0].trim();
    return `data:${mime};base64,${bytesToBase64(bytes)}`;
  } catch (err) {
    console.error("[wallpaper] fal failed:", err);
    return null;
  }
}

/**
 * Generate a background: fal.ai first (premium), then native Workers AI as a
 * fallback — each with a couple of retries for transient errors. Returns null
 * only if every path fails (the client then paints the brand gradient).
 */
async function generateBackground(env: Bindings, prompt: string, negative: string): Promise<string | null> {
  // 1) fal.ai FLUX.2 (primary)
  if (env.FAL_KEY) {
    for (let attempt = 0; attempt < 2; attempt++) {
      const url = await falImage(env, prompt);
      if (url) return url;
    }
  }
  // 2) Cloudflare Workers AI (fallback)
  for (const model of IMAGE_MODELS) {
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const url = await runImageModel(env, model, prompt, negative);
        if (url) return url;
      } catch (err) {
        console.error(`[wallpaper] ${model} attempt ${attempt + 1} failed:`, err);
      }
    }
  }
  return null;
}

/**
 * Vision-read the brand image into a short style descriptor (best-effort, cached
 * per domain) so the generated texture matches the brand's actual aesthetic.
 * Leonardo/Phoenix can't do img2img, so this is how we "use the brand image" —
 * the model describes it, and that description steers the text-to-image prompt.
 */
async function brandVibe(env: Bindings, source: string, imageUrl?: string): Promise<string | undefined> {
  if (!imageUrl) return undefined;
  const cacheKey = `wp:vibe:${source}`;
  try {
    const cached = await env.SCAN_COUNTERS.get(cacheKey);
    if (cached !== null) return cached || undefined;
  } catch {
    /* miss */
  }
  let vibe: string | undefined;
  try {
    const res = await fetch(imageUrl);
    if (res.ok) {
      const buf = new Uint8Array(await res.arrayBuffer());
      if (buf.length && buf.length <= 300_000) {
        const out = (await env.AI.run(VISION_MODEL, {
          image: [...buf],
          prompt:
            "Describe this brand's VISUAL STYLE as 4-6 short adjectives for an abstract wallpaper (e.g. 'sleek, futuristic, neon, dark'). Reply with ONLY comma-separated adjectives, no sentence.",
          max_tokens: 40,
        })) as { response?: string };
        const txt = (out?.response ?? "").replace(/\s+/g, " ").replace(/["'.]/g, "").trim();
        if (txt && txt.length <= 120) vibe = txt;
      }
    }
  } catch {
    /* best-effort */
  }
  try {
    await env.SCAN_COUNTERS.put(cacheKey, vibe ?? "", { expirationTtl: 86_400 });
  } catch {
    /* non-fatal */
  }
  return vibe;
}

/**
 * Turn a brand's title + description into a short visual SCENE MOTIF (what the
 * brand is about, as paintable nouns) so the "scene" style produces an on-theme
 * illustration — e.g. a game studio → "neon game worlds, arcade energy". Cached
 * per domain, best-effort (returns undefined → scene falls back to a stylish
 * abstract).
 */
async function brandMotif(
  env: Bindings,
  source: string,
  title: string,
  description?: string,
): Promise<string | undefined> {
  const cacheKey = `wp:motif:${source}`;
  try {
    const cached = await env.SCAN_COUNTERS.get(cacheKey);
    if (cached !== null) return cached || undefined;
  } catch {
    /* miss */
  }
  let motif: string | undefined;
  try {
    const brief = [title, description].filter(Boolean).join(" — ").slice(0, 400);
    const out = (await env.AI.run(TEXT_MODEL, {
      messages: [
        {
          role: "system",
          content:
            "You generate concise image-generation motifs. Given a brand, output 4-7 words of concrete VISUAL motifs (objects, environments, atmosphere) for an on-brand abstract wallpaper scene. No logos, no text, no brand names, no people. Reply with ONLY a comma-separated list, nothing else.",
        },
        { role: "user", content: `Brand: ${brief || source}` },
      ],
      max_tokens: 40,
    })) as { response?: string };
    const txt = (out?.response ?? "")
      .replace(/\s+/g, " ")
      .replace(/^["'\s]*(motifs?:)?\s*/i, "")
      .replace(/["'.]/g, "")
      .trim();
    if (txt && txt.length <= 140 && txt.includes(",")) motif = txt;
    else if (txt && txt.length <= 80) motif = txt;
  } catch {
    /* best-effort */
  }
  try {
    await env.SCAN_COUNTERS.put(cacheKey, motif ?? "", { expirationTtl: 86_400 });
  } catch {
    /* non-fatal */
  }
  return motif;
}

/**
 * A punchy 3-word brand tagline for the poster footer (e.g. "IMAGINE · BUILD ·
 * PLAY"). Generated from the brand, cached per domain, best-effort. Returns a
 * normalized "WORD · WORD · WORD" string, or undefined (footer is then omitted).
 */
async function brandTagline(
  env: Bindings,
  source: string,
  name: string,
  description?: string,
): Promise<string | undefined> {
  const cacheKey = `wp:tag:${source}`;
  try {
    const cached = await env.SCAN_COUNTERS.get(cacheKey);
    if (cached !== null) return cached || undefined;
  } catch {
    /* miss */
  }
  let tagline: string | undefined;
  try {
    const brief = [name, description].filter(Boolean).join(" — ").slice(0, 300);
    const out = (await env.AI.run(TEXT_MODEL, {
      messages: [
        {
          role: "system",
          content:
            "You write punchy 3-word brand taglines, each word a single imperative or noun, like 'IMAGINE. BUILD. PLAY.' or 'DESIGN. SHIP. SCALE.' or 'SCAN. CONNECT. GROW.'. Reply with ONLY three single uppercase words separated by ' . ', nothing else.",
        },
        { role: "user", content: `Brand: ${brief || source}` },
      ],
      max_tokens: 24,
    })) as { response?: string };
    // Keep only A-Z words; take up to 3; require at least 2 for a real tagline.
    const words = (out?.response ?? "")
      .toUpperCase()
      .split(/[^A-Z]+/)
      .filter((w) => w.length >= 2 && w.length <= 12)
      .slice(0, 3);
    if (words.length >= 2) tagline = words.join(" · ");
  } catch {
    /* best-effort */
  }
  try {
    await env.SCAN_COUNTERS.put(cacheKey, tagline ?? "", { expirationTtl: 86_400 });
  } catch {
    /* non-fatal */
  }
  return tagline;
}

export async function generateWallpaper(
  env: Bindings,
  rawUrl: string,
  opts: { style?: WallpaperStyle; placement?: WallpaperPlacement; targetUrl?: string } = {},
): Promise<WallpaperResult | null> {
  // The brand/theme (colours, logo, background) comes from `rawUrl`. The QR can
  // point somewhere else entirely (`targetUrl`) — e.g. a gamebyte.ai-styled
  // wallpaper whose code opens your personal LinkedIn. Defaults to rawUrl.
  const kit = await brandMatch(env, rawUrl);
  if (!kit) return null;
  const destination = (opts.targetUrl ?? "").trim() || rawUrl;

  const style: WallpaperStyle = WALLPAPER_STYLES.includes(opts.style as WallpaperStyle)
    ? (opts.style as WallpaperStyle)
    : "mesh";
  const placement: WallpaperPlacement = WALLPAPER_PLACEMENTS.includes(opts.placement as WallpaperPlacement)
    ? (opts.placement as WallpaperPlacement)
    : "center";

  // Cache the (expensive) background per domain+style. The version prefix lets us
  // invalidate stale backgrounds when the generation prompt changes.
  const cacheKey = `wp:v7:${kit.source}:${style}`;
  let backgroundDataUrl: string | null = null;
  try {
    backgroundDataUrl = await env.SCAN_COUNTERS.get(cacheKey);
  } catch {
    /* miss */
  }
  if (!backgroundDataUrl) {
    // Read the brand's visual style from its image (best-effort) so the texture
    // matches the brand's aesthetic — the closest these text-to-image models get
    // to using the image as a reference.
    const vibe = await brandVibe(env, kit.source, kit.imageUrl);
    // The "scene" style additionally pulls a subject motif from the brand's
    // description (what it does) for a thematic, illustrative background.
    const motif =
      style === "scene" ? await brandMotif(env, kit.source, kit.title, kit.description) : undefined;
    const prompt = buildWallpaperPrompt(kit.palette.accent, style, placement, vibe, motif);
    backgroundDataUrl = await generateBackground(env, prompt, WALLPAPER_NEGATIVE);
    if (backgroundDataUrl) {
      try {
        await env.SCAN_COUNTERS.put(cacheKey, backgroundDataUrl, { expirationTtl: 86_400 });
      } catch {
        /* non-fatal */
      }
    }
  }
  // If image gen is unavailable, the client paints a brand gradient instead —
  // the wallpaper never fully fails.
  const aiBackground = !!backgroundDataUrl;

  // The QR is always our programmatic, scannable code (brand-styled design),
  // encoding the chosen destination (not necessarily the theme source).
  let qrSvg: string;
  try {
    const matrix = encodeMatrix(buildPayload("url", { url: destination }), kit.design.ecc);
    qrSvg = renderSvg(matrix, kit.design);
  } catch {
    return null;
  }

  // Poster overlay text — crisp, brand-aligned, composited by the client (never
  // AI-drawn, so spelling and the logo are always correct).
  const wordmark = brandName(kit.title, kit.source);
  let subtitle = subtitleFrom(kit.description);
  // Drop a redundant leading "Brand is a/the …" so the subtitle doesn't echo the
  // wordmark. Word-wise so "is an" is fully removed (not left as a stray "n").
  if (subtitle && wordmark && subtitle.toLowerCase().startsWith(wordmark.toLowerCase() + " ")) {
    const filler = new Set(["is", "are", "a", "an", "the", "your", "—", "–", "-", ":"]);
    const words = subtitle.slice(wordmark.length).trim().split(/\s+/);
    while (words.length > 1 && filler.has(words[0].toLowerCase())) words.shift();
    subtitle = words.join(" ");
  }
  const tagline = await brandTagline(env, kit.source, wordmark, kit.description);

  return {
    backgroundDataUrl,
    aiBackground,
    gradient: gradientFromPalette(kit.palette),
    qrSvg,
    layout: placementLayout(placement),
    palette: kit.palette,
    title: kit.title,
    source: kit.source,
    target: displayHost(destination),
    style,
    logo: kit.logoDataUrl,
    wordmark,
    subtitle: subtitle || undefined,
    tagline,
    glow: glowColor(kit.palette.accent),
  };
}
